import { Link } from "@tanstack/react-router"
import type { ReactNode } from "react"
import { useIsMobile } from "@/shared/lib/use-mobile"
import { Button } from "@/shared/ui/button"
import { ArrowLeftIcon, ChevronRightIcon, PlusIcon, type Icon } from "@/shared/ui/icon"
import { useFullScreen, usePageChrome } from "./chrome"

/** 경로의 한 단계. 마지막 단계가 이 페이지다. */
export type Crumb = { label: string; href?: string; icon?: Icon }
export type CreateAction = { label: string; onClick: () => void }

type PageProps = {
  crumbs: Crumb[]
  /** 머리 줄 오른쪽: 페이지 메뉴(…) 같은 이 페이지 자체의 동작. */
  actions?: ReactNode
  /** 만들기. 데스크톱은 머리 줄 끝 버튼, 휴대폰은 하단 탭 위 FAB. */
  create?: CreateAction
  /** 툴바 왼쪽: 뷰 · 탭(PageViews). */
  views?: ReactNode
  /** 툴바 오른쪽: 필터 · 표시 · 검색 도구. */
  tools?: ReactNode
  /** 툴바 아래, 본문 위: 걸린 필터 줄 같은 것. */
  below?: ReactNode
  /** 상세 · 양식 페이지: 휴대폰에서 전체 화면(하단 탭 없이, 앱 바는 ← · 제목 · 페이지 메뉴만). */
  isFullScreen?: boolean
  /** 휴대폰 앱 바 ←를 위 단계 링크 대신 이 함수로 둔다(고친 것을 버릴지 먼저 묻는 수정 화면). */
  onBack?: () => void
  children: ReactNode
}

/**
 * 목록 같은 상위 페이지의 틀(호호코워크 Page). 데스크톱: 52px 머리 줄(경로 · 동작 · 만들기) + 44px 툴바(뷰 · 도구).
 * 휴대폰: 52px 앱 바(뒤로 · 제목 · 공통 도구) + 52px 도구 줄, 만들기는 FAB. 본문은 남은 높이를 채우고 스스로 스크롤한다.
 */
export function Page({ crumbs, actions, create, views, tools, below, isFullScreen = false, onBack, children }: PageProps) {
  const isMobile = useIsMobile()
  useFullScreen(isMobile && isFullScreen)
  const hasToolbar = Boolean(views || tools)
  return (
    <div data-slot="page" className="flex min-h-0 flex-1 flex-col">
      {isMobile ? <PageAppBar crumbs={crumbs} actions={actions} isFullScreen={isFullScreen} onBack={onBack} /> :<PageHeader crumbs={crumbs} actions={actions} create={create} />}
      {hasToolbar && (
        <div data-slot="page-toolbar" className="flex h-13 shrink-0 items-center gap-2 border-b px-4 md:h-11">
          <div className="flex min-w-0 flex-1 items-center gap-1.5 overflow-x-auto [scrollbar-width:none]">{views}</div>
          {tools && <div className="flex shrink-0 items-center gap-1.5">{tools}</div>}
        </div>
      )}
      {below}
      <div data-slot="page-body" className="relative flex min-h-0 flex-1 flex-col overflow-y-auto bg-dots">{children}</div>
      {isMobile && create && (
        <Button variant="create" size="icon-lg" aria-label={create.label} onClick={create.onClick}
          className="fixed right-4 bottom-[calc(4.5rem+env(safe-area-inset-bottom))] z-10 size-14 rounded-2xl">
          <PlusIcon className="size-6" />
        </Button>
      )}
    </div>
  )
}

/** 경로의 위 단계: 보조 글자색 · 500, 아이콘이 있으면 이름 앞에(프로젝트처럼). */
const MIDDLE_CRUMB = "flex shrink-0 items-center gap-1.5 font-medium text-muted-foreground hover:text-foreground [&_svg]:shrink-0"

/** 데스크톱 머리 줄: 왼쪽 경로(마지막은 아이콘과 이름, 위 단계도 아이콘이 있으면 함께), 오른쪽 동작과 만들기. */
function PageHeader({ crumbs, actions, create }: Pick<PageProps, "crumbs" | "actions" | "create">) {
  return (
    <header data-slot="page-header" className="flex h-13 shrink-0 items-center gap-2 border-b px-4">
      <nav aria-label="경로" className="flex min-w-0 flex-1 items-center gap-1 text-sm">
        {crumbs.map((crumb, index) => {
          const isLast = index === crumbs.length - 1
          return (
            <span key={`${crumb.label}-${index}`} className="flex min-w-0 items-center gap-1">
              {index > 0 && <ChevronRightIcon className="size-3.5 shrink-0 text-icon-muted" />}
              {isLast ? (
                <span aria-current="page" className="flex min-w-0 items-center gap-1.5 font-semibold">
                  {crumb.icon && <crumb.icon className="shrink-0" />}
                  <span className="truncate">{crumb.label}</span>
                </span>
              ) : crumb.href ? (
                <Link to={crumb.href} className={MIDDLE_CRUMB}>{crumb.icon && <crumb.icon className="text-icon-muted" />}{crumb.label}</Link>
              ) : (
                <span className={MIDDLE_CRUMB}>{crumb.icon && <crumb.icon className="text-icon-muted" />}{crumb.label}</span>
              )}
            </span>
          )
        })}
      </nav>
      {actions}
      {create && (
        <Button variant="create" onClick={create.onClick}>
          <PlusIcon data-icon="inline-start" />
          {create.label}
        </Button>
      )}
    </header>
  )
}

/** 휴대폰 앱 바: 위 단계가 있으면 ←, 이 페이지 이름, 페이지 메뉴, 오른쪽에 공통 도구(전체 화면이면 없음). */
function PageAppBar({ crumbs, actions, isFullScreen, onBack }: Pick<PageProps, "crumbs" | "actions" | "isFullScreen" | "onBack">) {
  const { tools: chrome } = usePageChrome()
  const current = crumbs[crumbs.length - 1]
  const parent = [...crumbs].slice(0, -1).reverse().find(crumb => crumb.href)
  return (
    <header data-slot="page-app-bar" className="flex h-13 shrink-0 items-center gap-1 border-b px-2">
      {onBack ? (
        <Button variant="ghost" size="icon" aria-label={parent ? `${parent.label}(으)로` : "뒤로"} onClick={onBack}>
          <ArrowLeftIcon />
        </Button>
      ) : parent?.href ? (
        <Button variant="ghost" size="icon" aria-label={`${parent.label}(으)로`} nativeButton={false} render={<Link to={parent.href} />}>
          <ArrowLeftIcon />
        </Button>
      ) : (
        current.icon && <current.icon className="mx-2 size-6 shrink-0" />
      )}
      <h1 className="min-w-0 truncate text-base font-semibold">{current.label}</h1>
      {actions}
      {!isFullScreen && <div className="ml-auto flex shrink-0 items-center gap-0.5">{chrome}</div>}
    </header>
  )
}

import { cn } from "@/shared/lib/utils"
import { Button } from "@/shared/ui/button"
import type { Icon } from "@/shared/ui/icon"

export type PageView<T extends string> = { value: T; label: string; icon?: Icon }

/**
 * 뷰 · 탭 알약 줄. 지금 뷰는 한 단계 진한 바탕과 Bold Duotone 아이콘이다. compact면(휴대폰에서 자리가 좁을 때) 아이콘만 둔다.
 */
export function PageViews<T extends string>({ views, value, onChange, label, isCompact }: {
  views: PageView<T>[]; value: T; onChange: (value: T) => void; label: string; isCompact?: boolean
}) {
  return (
    <div role="tablist" aria-label={label} className="flex items-center gap-1.5">
      {views.map(view => {
        const isCurrent = view.value === value
        return (
          <Button key={view.value} role="tab" aria-selected={isCurrent} aria-label={isCompact ? view.label : undefined}
            variant={isCurrent ? "view-active" : "view"} size={isCompact ? "icon" : "default"} onClick={() => onChange(view.value)}
            className={cn("max-md:h-11 max-md:[&_svg]:size-6", isCompact ? "max-md:w-11" : "px-3 max-md:px-4")}>
            {view.icon && <view.icon chosen={isCurrent} data-icon="inline-start" />}
            {!isCompact && view.label}
          </Button>
        )
      })}
    </div>
  )
}

/** 툴바 도구(필터 · 표시) 귀퉁이의 점: 걸렸거나 처음과 다를 때. 개수는 읽기용 이름에만 둔다. */
export function ToolDot({ label }: { label: string }) {
  return <span role="status" aria-label={label} className="absolute -top-0.5 -right-0.5 size-2 rounded-full bg-primary ring-2 ring-background" />
}

import { createContext, useContext, useLayoutEffect, type ReactNode } from "react"

/**
 * 셸과 페이지 사이의 약속. 셸은 휴대폰 앱 바 오른쪽의 공통 도구(검색 · 알림함 · 내 아바타)를 넣고,
 * 상세 · 양식 페이지는 휴대폰에서 전체 화면(하단 탭 없음)을 셸에 알린다(호호코워크 휴대폰 화면 구조).
 */
type PageChrome = { tools: ReactNode; setFullScreen: (isFullScreen: boolean) => void }

const PageChromeContext = createContext<PageChrome>({ tools: null, setFullScreen: () => {} })

export const PageChromeProvider = PageChromeContext.Provider
export const usePageChrome = () => useContext(PageChromeContext)

/** 이 페이지가 떠 있는 동안 휴대폰 하단 탭을 숨긴다. */
export function useFullScreen(isFullScreen: boolean) {
  const { setFullScreen } = usePageChrome()
  useLayoutEffect(() => {
    if (!isFullScreen) return undefined
    setFullScreen(true)
    return () => setFullScreen(false)
  }, [isFullScreen, setFullScreen])
}
